<div class="card"><form method="get" action="<?= $link('/search') ?>" class="search-filters"><?= $routeInput('/search') ?><label>Search<input name="q" value="<?= $e($query) ?>" placeholder="Titles, article content and asset fields" maxlength="200"></label><label>Organization<select name="organization"><option value="">All assigned organizations</option><?php foreach($organizations as $o): ?><option value="<?= $e($o['id']) ?>" <?= $selectedOrg===(int)$o['id']?'selected':'' ?>><?= $e($o['name']) ?></option><?php endforeach; ?></select></label><label>Record type<select name="type"><option value="">All record types</option><?php foreach(['asset','article','contact','location'] as $type): ?><option value="<?= $e($type) ?>" <?= $selectedType===$type?'selected':'' ?>><?= $e(ucfirst($type)) ?></option><?php endforeach; ?></select></label><button class="button">Search</button></form></div>
<?php if($query!==''): ?><p class="muted"><?= $e($result['total']) ?> results for “<?= $e($query) ?>”</p><?php endif; ?><div class="search-results"><?php foreach($result['items'] as $r): ?><article class="card"><div class="eyebrow"><?= $e($r['organization_name'].' · '.$r['type']) ?></div><h2><a href="<?= $link('/records/'.$r['id']) ?>"><?= $e($r['title']) ?></a></h2><p class="muted"><?= $e($r['snippet']) ?></p></article><?php endforeach; ?></div>
<?php $page=$result['page'];$params=['q'=>$query,'organization'=>$selectedOrg,'type'=>$selectedType]; ?><div class="pagination"><?php if($page>1): ?><a href="<?= $link('/search?'.http_build_query($params+['page'=>$page-1])) ?>">← Previous</a><?php endif; ?><?php if($page*25<$result['total']): ?><a href="<?= $link('/search?'.http_build_query($params+['page'=>$page+1])) ?>">Next →</a><?php endif; ?></div>
